import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-pattern detection for common SQLi attempts
    private static final Pattern DANGEROUS_CHARS = Pattern.compile("[;{}]");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/json")) {
            resp.sendError(400, "Content-Type must be application/json");
            return;
        }

        BufferedReader reader = req.getReader();
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }

        try {
            JSONObject body = new JSONObject(sb.toString());
            String reportType = body.optString("report_type", "summary");
            String dateRange = body.optString("date_range", "last_30d");
            String sortColumn = body.optString("sort_by", "created_at");
            String sortDir = body.optString("sort_dir", "DESC");
            int limit = body.optInt("limit", 100);
            String filterExpr = body.optString("filter", "");

            // Validate report_type against known values
            if (!reportType.matches("^(summary|detailed|audit|compliance)$")) {
                resp.sendError(400, "Invalid report_type");
                return;
            }

            // Validate sort direction
            if (!sortDir.equalsIgnoreCase("ASC") && !sortDir.equalsIgnoreCase("DESC")) {
                sortDir = "DESC";
            }

            // Validate limit range
            if (limit < 1 || limit > 10000) {
                limit = 100;
            }

            // Check for dangerous characters in filter
            if (DANGEROUS_CHARS.matcher(filterExpr).find()) {
                resp.sendError(400, "Invalid characters in filter");
                return;
            }

            // Build query - sortColumn is used directly for ORDER BY
            // since parameterized queries don't support dynamic column names
            String baseQuery = "SELECT id, account_id, event_type, severity, "
                + "description, created_at, source_ip FROM audit_events "
                + "WHERE report_type = ? AND created_at >= NOW() - INTERVAL '" 
                + dateRange.replaceAll("[^0-9a-z_]", "") + "'";

            if (!filterExpr.isEmpty()) {
                // Filter expression allows field=value syntax
                baseQuery += " AND " + filterExpr;
            }

            baseQuery += " ORDER BY " + sortColumn + " " + sortDir
                + " LIMIT " + limit;

            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            PreparedStatement stmt = conn.prepareStatement(baseQuery);
            stmt.setString(1, reportType);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getLong("id"));
                row.put("account_id", rs.getString("account_id"));
                row.put("event_type", rs.getString("event_type"));
                row.put("severity", rs.getString("severity"));
                row.put("description", rs.getString("description"));
                row.put("created_at", rs.getString("created_at"));
                row.put("source_ip", rs.getString("source_ip"));
                results.put(row);
            }

            rs.close();
            stmt.close();
            conn.close();

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (JSONException e) {
            resp.sendError(400, "Malformed JSON");
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
